import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function Login() {
  // const [isSignup, setIsSignup] = useState(false);
  // const [hoverSignUp, setHoverSignUp] = useState(false);
  // const [hoverSignIn, setHoverSignIn] = useState(false);

  const navigate = useNavigate();

  const [form, setForm] = useState({
    name: "",
    email: ""
  });

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!isSignup) {
      // LOGIN
      const storedUsers =
        JSON.parse(localStorage.getItem("users")) || [];

      const allUsers = [...dummyUsers, ...storedUsers];

      const foundUser = allUsers.find(
        (u) =>
          u.email === form.email &&
          u.password === form.password
      );

      if (!foundUser) {
        alert("Invalid email or password ❌");
        return;
      }

      const user = {
        name: foundUser.name,
        email: foundUser.email,
        role: foundUser.role,
        token: "dummy-token",
      };

      localStorage.setItem("user", JSON.stringify(user));

      // ⭐ Trigger update
      window.dispatchEvent(new Event("authChanged"));

      alert("Login Successful ✅");

      navigate("/");
    } else {
      // SIGNUP
      let users =
        JSON.parse(localStorage.getItem("users")) || [];

      const exists = [...dummyUsers, ...users].find(
        (u) => u.email === form.email
      );

      if (exists) {
        alert("User already exists ❌");
        return;
      }

      users.push(form);
      localStorage.setItem("users", JSON.stringify(users));

      alert("Registered Successfully ✅");

      setIsSignup(false);
    }
  };

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h2>{isSignup ? "Create Account" : "Welcome Back 👋"}</h2>

        <form onSubmit={handleSubmit} style={styles.form}>
          {isSignup && (
            <div style={styles.inputBox}>
              <span>👤</span>
              <input
                style={styles.input}
                placeholder="Full Name"
                onChange={(e) =>
                  setForm({ ...form, name: e.target.value })
                }
              />
            </div>
          )}

          <div style={styles.inputBox}>
            <span>📧</span>
            <input
              style={styles.input}
              placeholder="Email"
              onChange={(e) =>
                setForm({ ...form, email: e.target.value })
              }
            />
          </div>

          <div style={styles.inputBox}>
            <span>🔒</span>
            <input
              type="password"
              style={styles.input}
              placeholder="Password"
              onChange={(e) =>
                setForm({ ...form, password: e.target.value })
              }
            />
          </div>

          {isSignup && (
            <select
              style={styles.select}
              value={form.role}
              onChange={(e) =>
                setForm({ ...form, role: e.target.value })
              }
            >
              <option value="PATIENT">Patient</option>
              <option value="DOCTOR">Doctor</option>
              <option value="ADMIN">Admin</option>
            </select>
          )}

          {!isSignup ? (
            <p style={styles.switchText}>
              New user?{" "}
              <span
                onClick={() => setIsSignup(true)}
                onMouseEnter={() => setHoverSignUp(true)}
                onMouseLeave={() => setHoverSignUp(false)}
                style={
                  hoverSignUp ? styles.hoverLink : styles.link
                }
              >
                Sign Up
              </span>
            </p>
          ) : (
            <p style={styles.switchText}>
              Already have an account?{" "}
              <span
                onClick={() => setIsSignup(false)}
                onMouseEnter={() => setHoverSignIn(true)}
                onMouseLeave={() => setHoverSignIn(false)}
                style={
                  hoverSignIn ? styles.hoverLink : styles.link
                }
              >
                Sign In
              </span>
            </p>
          )}

          <button style={styles.button}>
            {isSignup ? "Register" : "Login"}
          </button>
        </form>
      </div>
    </div>
  );














}

const styles = {
  page: {
    height: "100vh",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background: "linear-gradient(135deg, #1976d2, #42a5f5)",
  },
  card: {
    width: "350px",
    padding: "30px",
    borderRadius: "15px",
    background: "#fff",
    boxShadow: "0 10px 25px rgba(0,0,0,0.2)",
  },
  form: {
    display: "flex",
    flexDirection: "column",
    gap: "12px",
    marginTop: "15px",
  },
  inputBox: {
    display: "flex",
    alignItems: "center",
    border: "1px solid #ddd",
    borderRadius: "8px",
    padding: "10px",
    background: "#fafafa",
  },
  input: {
    border: "none",
    outline: "none",
    width: "100%",
    marginLeft: "8px",
    background: "transparent",
  },
  select: {
    padding: "10px",
    borderRadius: "8px",
    border: "1px solid #ddd",
  },
  switchText: {
    fontSize: "14px",
    textAlign: "center",
  },
  link: {
    color: "#1976d2",
    cursor: "pointer",
    transition: "0.3s",
  },
  hoverLink: {
    color: "#0d47a1",
    textDecoration: "underline",
    cursor: "pointer",
  },
  button: {
    padding: "12px",
    borderRadius: "8px",
    border: "none",
    background: "#1976d2",
    color: "#fff",
    fontWeight: "bold",
    cursor: "pointer",
  },
};

export default Login;
